css:
#tongsci1-3-2-2-3-egg .eg-body { grid-template-columns: 1040px minmax(0, 1fr); }
.eg-stage { position: relative; border: 2px solid var(--ink); border-radius: 12px; overflow: hidden; background: #f6efe0; }
.eg-stage canvas { touch-action: none; cursor: grab; user-select: none; -webkit-user-select: none; }
.eg-stage canvas.holding { cursor: grabbing; }
.eg-stage .u-vid video { width: 72%; height: auto; image-rendering: auto; }
.eg-panel { gap: 10px; }
.eg-out { margin: 0; font-size: 20px; line-height: 1.5; background: #fffbe6; border: 2px solid var(--accent); border-radius: 12px; padding: 8px 14px; min-height: 4.6em; flex: none; }
.eg-out b { color: var(--accent); }
.eg-tab { width: 100%; border-collapse: collapse; table-layout: fixed; font: 600 18px/1.25 var(--f-body); flex: none; background: var(--paper-2); border: 2px solid var(--ink); }
.eg-tab th { font: 700 16px/1.2 var(--f-body); background: color-mix(in srgb, var(--accent) 10%, var(--paper-2)); border: 1.5px solid var(--ink-3); padding: 5px 3px; }
.eg-tab th small { font-size: 13px; font-weight: 600; }
.eg-tab th:first-child { width: 26%; }
.eg-tab td { border: 1.5px solid var(--rule, #c9ccd3); padding: 2px 3px; text-align: center; height: 32px; font-size: 17px; }
.eg-tab td b { font-family: var(--f-mono); }
.eg-tab tr.hl td { background: color-mix(in srgb, var(--hl) 40%, #fff); }
.eg-facts { display: grid; grid-template-columns: auto 1fr; gap: 5px 12px; margin: 0; font-size: 18px; line-height: 1.42; flex: none; }
.eg-facts dt { font-weight: 800; color: var(--accent); white-space: nowrap; }
.eg-facts dd { margin: 0; }
section.ex.u-done .eg-facts { display: none; }

